#include <stdio.h>

int main(void) {
    int S, T, P;
    scanf("%d %d %d", &S, &T, &P);

    int altura[200];
    for (int i = 0; i < S; i++) {
        scanf("%d", &altura[i]);
    }

    int adj[200][200] = {0};
    for (int i = 0; i < T; i++) {
        int I, J;
        scanf("%d %d", &I, &J);
        I--;
        J--;
        adj[I][J] = adj[J][I] = 1;
    }

    int ordem[200];
    for (int i = 0; i < S; i++) {
        ordem[i] = i;
        for (int j = i; j > 0 && altura[ordem[j]] < altura[ordem[j - 1]]; j--) {
            int temp = ordem[j];
            ordem[j] = ordem[j - 1];
            ordem[j - 1] = temp;
        }
    }

    int dp[200] = {0};
    for (int i = 0; i < S; i++) {
        int u = ordem[i];
        for (int v = 0; v < S; v++) {
            if (adj[u][v] && altura[u] > altura[v]) {
                if (dp[u] < dp[v] + 1) {
                    dp[u] = dp[v] + 1;
                }
            }
        }
    }

    printf("%d\n", dp[P - 1]);
    return 0;
}
